<script setup lang="ts">
import {computed,onMounted,ref} from 'vue';import {useJourneyStore} from './stores/journey';import type {SessionUser} from './api';import AppIcon from './components/AppIcon.vue';import JourneyMap from './components/JourneyMap.vue';import JourneyTimeline from './components/JourneyTimeline.vue';import AccountPanel from './components/AccountPanel.vue';import CatalogPanel from './components/CatalogPanel.vue';import AdminPanel from './components/AdminPanel.vue';
type Stop={id:string;name:string};type Line={id:string;shortName:string;name:string;provenance:string;stopIds:string[]};
const store=useJourneyStore();const origin=ref('tropical'),destination=ref('partage'),date=ref('2026-10-28'),time=ref('07:20'),walk=ref(800),transfers=ref(2),menu=ref(false),locationMessage=ref(''),stops=ref<Stop[]>([]),lines=ref<Line[]>([]),catalogLoading=ref(true),catalogError=ref(''),user=ref<SessionUser|null>(null);const hasResults=computed(()=>store.journeys.length>0);const originName=computed(()=>stops.value.find(s=>s.id===origin.value)?.name??origin.value);const destinationName=computed(()=>stops.value.find(s=>s.id===destination.value)?.name??destination.value);
function swap(){[origin.value,destination.value]=[destination.value,origin.value]}function locate(){if(!navigator.geolocation){locationMessage.value='Localização não disponível neste navegador.';return}locationMessage.value='Aguardando sua autorização…';navigator.geolocation.getCurrentPosition(()=>locationMessage.value='Localização obtida apenas para esta busca; ela não será armazenada.',()=>locationMessage.value='Localização negada. Escolha uma parada ou ponto no campo de origem.',{timeout:6000})}function plan(){store.plan({originId:origin.value,destinationId:destination.value,serviceDate:date.value,departure:time.value,maxWalkMeters:walk.value,maxTransfers:transfers.value,preference:'FASTEST'})}
async function loadCatalog(){catalogLoading.value=true;catalogError.value='';try{const response=await fetch('/api/public/transit/catalog',{signal:AbortSignal.timeout(8000)});if(!response.ok)throw new Error();const data=await response.json();stops.value=data.stops;lines.value=data.lines;return true}catch{catalogError.value='Catálogo indisponível. Nenhuma lista substituta foi usada.';return false}finally{catalogLoading.value=false}}
onMounted(async()=>{if(await loadCatalog())plan()})
</script>
<template>
  <div class="app-frame">
    <header class="topbar"><a class="brand" href="#main" aria-label="OinbuPebas, início"><svg viewBox="0 0 40 44" aria-hidden="true"><path d="M21 2C9 9 4 22 9 34c9-3 15-13 12-32Z" /><path d="M25 12c10 5 14 15 9 25-8 1-14-6-9-25Z" class="accent" /><path d="M7 39c8-6 17-8 28-6" fill="none" /></svg><strong>OinbuPebas</strong></a><div class="academic"><AppIcon name="info" /><span>Projeto acadêmico — veículos e estimativas simulados. <br>Não utilize como única referência para deslocamentos reais.</span></div><button class="nav-toggle" aria-controls="main-navigation" :aria-expanded="menu" @click="menu=!menu"><AppIcon :name="menu?'close':'menu'" /><span class="sr-only">{{ menu?'Fechar':'Abrir' }} navegação</span></button><nav id="main-navigation" :class="{open:menu}" aria-label="Navegação principal"><a href="#planner" @click="menu=false">Planejar</a><a href="#lines" @click="menu=false">Linhas</a><a href="#account" @click="menu=false">Favoritos</a><a v-if="user?.role==='ADMIN'" href="#admin" @click="menu=false">Administração</a><a class="login" href="#account" @click="menu=false">{{ user?user.name:'Entrar' }}</a></nav></header>
    <main id="main">
      <section id="planner" class="planner"><aside class="search-panel"><header><h1>Planeje seu caminho</h1><p>Compare etapas, espera e baldeações antes de sair.</p></header><form @submit.prevent="plan"><label for="origin">Origem</label><div class="field"><AppIcon name="pin" /><select id="origin" v-model="origin" :disabled="catalogLoading||!!catalogError"><option v-for="stop in stops" :key="stop.id" :value="stop.id">{{ stop.name }}</option></select></div><button type="button" class="swap" aria-label="Inverter origem e destino" :disabled="!stops.length" @click="swap"><AppIcon name="swap" /></button><label for="destination">Destino</label><div class="field destination"><AppIcon name="pin" /><select id="destination" v-model="destination" :disabled="catalogLoading||!!catalogError"><option v-for="stop in stops" :key="stop.id" :value="stop.id">{{ stop.name }}</option></select></div><p v-if="catalogError" class="field-message" role="alert">{{ catalogError }}</p><div class="twocol"><div><label for="date">Data</label><input id="date" v-model="date" type="date"></div><div><label for="time">Saída</label><input id="time" v-model="time" type="time"></div></div><details><summary>Preferências de trajeto</summary><label for="walk">Caminhada máxima · {{ walk }} m</label><input id="walk" v-model.number="walk" type="range" min="100" max="2000" step="100"><label for="transfers">Baldeações máximas</label><select id="transfers" v-model.number="transfers"><option :value="0">Nenhuma</option><option :value="1">Uma</option><option :value="2">Duas</option></select></details><button type="button" class="locate" @click="locate"><AppIcon name="locate" />Usar minha localização</button><p v-if="locationMessage" class="field-message" role="status">{{ locationMessage }}</p><button class="primary" :disabled="store.loading||!stops.length"><span v-if="store.loading" class="loader"></span>{{ store.loading?'Buscando horários…':catalogLoading?'Carregando catálogo…':'Buscar trajetos' }}</button></form><div class="source-note"><AppIcon name="info" /><p><strong>Dados demonstrativos</strong><br>Conexões e horários são sintéticos e podem não refletir a operação real.</p></div></aside><JourneyMap :active="hasResults" /></section>
      <section class="results" aria-live="polite"><div v-if="store.error" class="error-banner" role="alert"><strong>Consulta online indisponível</strong><span>{{ store.error }} Nenhum resultado local foi usado no lugar da API.</span><button @click="plan">Tentar novamente</button></div><header class="results-heading"><div><h2>Trajetos encontrados</h2><p v-if="hasResults">{{ store.journeys.length }} alternativa{{ store.journeys.length===1?'':'s' }} · {{ originName }} → {{ destinationName }}</p><p v-else-if="store.searched&&!store.loading&&!store.error">Sem serviço no horário informado. Tente ampliar a caminhada ou mudar a saída.</p><p v-else-if="store.loading">Consultando horários do catálogo ativo…</p></div><span class="data-label">Dados sintéticos</span></header><div v-if="hasResults" class="results-grid"><div class="alternatives" role="list" aria-label="Alternativas de trajeto"><button v-for="journey in store.journeys" :key="journey.id" role="listitem" :aria-pressed="store.selected?.id===journey.id" :class="['journey-option',{selected:store.selected?.id===journey.id}]" @click="store.selectedId=journey.id"><span class="option-label">{{ journey.label }}</span><strong>{{ journey.durationMinutes }} min</strong><span>{{ journey.departure }} → {{ journey.arrival }}</span><small><AppIcon name="walk" /> {{ journey.walkingMinutes }} min <AppIcon name="clock" /> {{ journey.waitingMinutes }} min <AppIcon name="swap" /> {{ journey.transfers }} baldeação{{ journey.transfers===1?'':'s' }}</small></button></div><JourneyTimeline v-if="store.selected" :key="store.selected.id" :journey="store.selected" /></div></section>
      <CatalogPanel :lines="lines" :loading="catalogLoading" :error="catalogError" />
      <AccountPanel :origin-id="origin" :destination-id="destination" @user="user=$event" />
      <AdminPanel v-if="user?.role==='ADMIN'" />
    </main><footer><span>OinbuPebas · Projeto acadêmico independente</span><span>O transporte real continua normalmente se esta plataforma estiver indisponível.</span></footer>
  </div>
</template>
